using System.IO;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace MXBRaceDayLive.Profile;

internal static class ThemeArt
{
    private static readonly ImageSource HeaderImage = Load(@"[... ELLIPSIZATION ...]");

    public static ImageBrush HeaderBrush() => NewBrush(new Rect(0, 0, 1, 1));
    public static ImageBrush RiderBrush() => NewBrush(new Rect(0.30, 0.00, 0.39, 1.00));
    public static ImageBrush LiveBrush() => NewBrush(new Rect(0.66, 0.00, 0.34, 1.00));
    public static ImageBrush LogoBrush() => NewBrush(new Rect(0.00, 0.00, 0.40, 1.00));

    private static ImageBrush NewBrush(Rect viewbox)
    {
        var brush = new ImageBrush(HeaderImage)
        {
            Stretch = Stretch.UniformToFill,
            AlignmentX = AlignmentX.Center,
            AlignmentY = AlignmentY.Center,
            ViewboxUnits = BrushMappingMode.RelativeToBoundingBox,
            Viewbox = viewbox
        };
        brush.Freeze();
        return brush;
    }

    private static ImageSource Load(string base64)
    {
        var bytes = Convert.FromBase64String(base64);
        using var stream = new MemoryStream(bytes);
        var bitmap = new BitmapImage();
        bitmap.BeginInit();
        bitmap.CacheOption = BitmapCacheOption.OnLoad;
        bitmap.StreamSource = stream;
        bitmap.EndInit();
        bitmap.Freeze();
        return bitmap;
    }
}
